// Validates the Config node (plus optional webhook overrides) and produces ONE clean config object.
const KEYS = ['start_mode','icp','target_titles','signals','signals_source','signals_url','companies_source','companies_url','companies_json','contacts_source','contacts_url','contacts_per_company','email_pattern','leads_json','dns_resolver_url','research_source','research_url','min_confidence','company_name','product_summary','value_prop','tone','sender_first_name','signature','email_mode','max_words','allow_links','outreach_mode','mailbox_from','sequence_api_url','dry_run','allow_guessed_sends','allow_webhook_live_send','allow_private_urls','max_leads','max_sends_per_run','throttle_seconds','callback_url'];
const OVERRIDABLE = new Set(['start_mode','icp','target_titles','signals','companies_json','leads_json','contacts_source','research_source','email_mode','max_leads','min_confidence','max_words','tone','value_prop','product_summary','company_name','sender_first_name','signature','dry_run','callback_url']);
const ENUM = {
  start_mode: ['from_icp', 'have_leads'],
  signals_source: ['icp_only', 'http'],
  companies_source: ['inline', 'http'],
  contacts_source: ['provided', 'provider_http', 'guess_syntax'],
  email_pattern: ['first.last', 'flast', 'first', 'firstlast', 'first_last', 'f.last'],
  research_source: ['llm_only', 'http_search'],
  email_mode: ['body_only', 'full_email'],
  outreach_mode: ['log_only', 'mailbox', 'sequence_api']
};
const base = $input.first().json || {};
const viaWebhook = base.headers !== undefined && base.body !== undefined;
// A bad webhook call gets an HTTP 400 with the reason. A bad manual run stops with the error shown on this node.
function run() {
const body = (viaWebhook && base.body && typeof base.body === 'object' && !Array.isArray(base.body)) ? base.body : {};
const cfg = {};
for (const k of KEYS) cfg[k] = base[k];
const warnings = [];
if (viaWebhook) {
  for (const k of Object.keys(body)) {
    if (!OVERRIDABLE.has(k)) { warnings.push('ignored_override:' + k); continue; }
    cfg[k] = body[k];
  }
  if ('dry_run' in body) {
    cfg.dry_run = body.dry_run;
    if (body.dry_run === false && base.allow_webhook_live_send !== true) { cfg.dry_run = true; warnings.push('webhook_cannot_turn_dry_run_off'); }
  }
}
const str = (v, max) => (v === undefined || v === null ? '' : String(v)).trim().slice(0, max);
for (const k of Object.keys(ENUM)) {
  const v = str(cfg[k], 40);
  if (!ENUM[k].includes(v)) throw new Error('Config "' + k + '" must be one of: ' + ENUM[k].join(', ') + ' (got "' + v + '")');
  cfg[k] = v;
}
