for (const k of ['company_name','sender_first_name']) cfg[k] = str(cfg[k], 120);
for (const k of ['product_summary','value_prop','tone']) cfg[k] = str(cfg[k], 1500);
cfg.signature = str(cfg.signature, 400);
cfg.max_leads = Math.round(PAE.num(cfg.max_leads, 1, 100, 10));
cfg.contacts_per_company = Math.round(PAE.num(cfg.contacts_per_company, 1, 5, 2));
cfg.max_sends_per_run = Math.round(PAE.num(cfg.max_sends_per_run, 0, 200, 25));
cfg.throttle_seconds = Math.round(PAE.num(cfg.throttle_seconds, 0, 600, 30));
cfg.max_words = Math.round(PAE.num(cfg.max_words, 40, 250, 120));
