const mustFill = ['company_name', 'product_summary', 'value_prop', 'sender_first_name', 'signature'].concat(cfg.start_mode === 'from_icp' ? ['icp', 'target_titles'] : []);
for (const k of mustFill) if (/REPLACE ME/i.test(cfg[k])) throw new Error('Config "' + k + '" still has the REPLACE ME placeholder. Edit the Config node first.');
